def analyze_patterns():
    inputs = ['uu', 'bhexg', 'yzzh', 'fcee', 'giczf']
    outputs = ['uu', 'bhhexg', 'yzzh', 'fxhe', 'giczf']

    # Let's look at differences
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        print(f"Input: '{inp}' -> Output: '{out}'")
        if inp != out:
            # Find where they differ
            min_len = min(len(inp), len(out))
            for j in range(min_len):
                if inp[j] != out[j]:
                    print(f"  First difference at pos {j}: '{inp[j]}' vs '{out[j]}'")
                    break
            else:
                if len(inp) != len(out):
                    print(f"  Length differs: {len(inp)} vs {len(out)}")

